  ('kitchen.plate5', 'The Kitchen strip — 5th photograph', 'Assorted pkhali with warm cornbread', false, 1100, 546, 80),
  ('kitchen.plate6', 'The Kitchen strip — 6th photograph', 'Shoti’s puri, canoe-shaped Georgian bread with ajika', false, 1100, 566, 90),
  ('kitchen.plate7', 'The Kitchen strip — 7th photograph', 'Tolma — grape leaves with garlic sour cream', false, 1100, 560, 100),
  ('kitchen.plate8', 'The Kitchen strip — 8th photograph', 'The Georgian salad with walnut dressing', false, 1100, 574, 110),
  ('kitchen.plate9', 'The Kitchen strip — 9th photograph', 'Layered honey cake with pistachio', false, 1100, 570, 120),
